using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("playing={0}; paused={1}; camera={2}; output={3}x{4}; pose={5}/{6}; current pipeline={7}; quality pipeline={8}; background={9}; profiler={10}; timeScale={11}", EditorApplication.isPlaying, EditorApplication.isPaused, Camera.main.name, Camera.main.pixelWidth, Camera.main.pixelHeight, Camera.main.transform.position, Camera.main.transform.eulerAngles, GraphicsSettings.currentRenderPipeline.name, QualitySettings.renderPipeline.name, Application.runInBackground, UnityEngine.Profiling.Profiler.enabled, Time.timeScale);
            int temp = 0;
            foreach (var o in Resources.FindObjectsOfTypeAll<ScriptableObject>())
                if (o.name == "VSM_Repaint_Capture_Pipeline_Temporary" || o.name == "VSM_Repaint_Capture_Graph_Temporary")
                    temp++;
            result.Log("temporary capture objects={0}", temp);
        }
    }
}
